    /// 219차(사용자: 스토리 자막·대사 영어화): 한국어 원문(키) → 영어. 영어 외 언어(ja·es)는 Loc.Tr 이 영어를 키로 번역표에서 찾는다.
    public static class StoryEn
    {
        /// 한국어 모드면 원문, 아니면 영어(→ 현재 언어 번역표). 표에 없으면 원문 그대로.
        public static string T(string ko)
