        }
        /// 영어 원문만(없으면 null).
        public static string En(string ko) => !string.IsNullOrEmpty(ko) && Map.TryGetValue(ko, out var en) ? en : null;

        private static readonly Dictionary<string, string> Map = new Dictionary<string, string>
        {
            { "그 약속", "That Promise" },
            { "너와 나의 주파수", "Our Frequency" },
            { "우리의 송전탑  ·  OUR FREQUENCY", "Our Tower  ·  OUR FREQUENCY" },
            { "검은 차가 출발했다. 나는 뒷유리를 손바닥으로 두드렸다. 창이 내려갔다.", "The black car pulled away. I pounded the rear window with my palm. The window rolled down." },
            { "「스무 살 네 생일에 송전탑 아래서 보자! 꼭!」 차가 흙먼지 속으로 멀어졌다.", "“On your 20th birthday, under the tower! Promise!” The car faded into the dust." },
            { "그날 밤. 달력의 내 생일에 동그라미를 치고 썼다. 「송전탑 아래.」 연필이 종이를 팼다.", "That night I circled my birthday on the calendar and wrote, “Under the tower.” The pencil dug into the paper." },
            { "달력이 일곱 번 바뀌었다. 동그라미는 해마다 같은 날에 있었다.", "The calendar changed seven times. The circle was on the same day every year." },
            { "일곱 번째 봄. 담요 끝이 바람에 들썩였다. 머리 위에서 쇠가 웅웅 울었다.", "The seventh spring. The edge of a blanket lifted in the wind. Overhead, the steel hummed." },
            { "모르는 얼굴", "A Face I Don't Know" },
            { "눈을 떴다. 낡은 담요 위였다. 바람이 담요 끝을 자꾸 들췄다.", "I opened my eyes. I was on an old blanket. The wind kept lifting its edge." },
            { "머리 위로 녹슨 쇠기둥이 하늘까지 올라가 있었고, 바람에 쇠가 웅웅 울었다. 하늘은 잿빛이었다.", "A rusty steel tower rose over my head into the sky, humming in the wind. The sky was gray." },
            { "파도가 방파제를 넘어 하얗게 부서졌다. 멀리 마을 스피커의 태풍 경보 방송이 바람에 끊어질 듯 이어졌다.", "Waves broke white over the seawall. Far off, the village speaker's typhoon warning kept cutting out in the wind." },
            { "이름을 떠올리려고 했다. 안 나왔다. 엄마 얼굴도, 집도, 어제도. 아무것도.", "I tried to remember my name. Nothing came. Not Mom's face, not home, not yesterday. Nothing." },
            { "기둥을 짚고 일어났다. 다리가 후들거렸다. 바위 웅덩이에 얼굴이 비쳤다.", "I pushed up against the post. My legs shook. My face showed in a rock pool." },
            { "웅덩이 속 여자애를 한참 봤다. 이름이 안 나왔다.", "I looked at the girl in the pool for a long time. No name came." },
            { "담요 위에 주저앉아 울었다. 소리를 내서 울었다. 왜 우는지도 몰랐다. 무서웠다. 그냥 무서웠다.", "I sank down on the blanket and cried. Out loud. I didn't even know why. I was scared. Just scared." },
            { "돌 세 개 옆에 주황 우비를 눌러쓴 꼬마가 앉아 있었다. 여섯 살쯤. 내가 우는 걸 다 보고 있었다.", "By three stones sat a kid, orange raincoat hood pulled low. About six. He'd watched me cry the whole time." },
            { "「누나, 이름 몰라?」 고개를 끄덕였다. 꼬마는 놀라지 않았다. 「그럼 바다누나. 눈이 바다처럼 파래.」", "“Sis, you don't know your name?” I nodded. The kid wasn't surprised. “Then Sister Bada. Your eyes are blue like the sea.”" },
            { "꼬마 손을 잡고 마을로 내려갔다. 바람에 등이 떠밀렸다.", "I held the kid's hand and went down to the village. The wind pushed at my back." },
            { "골목마다 사람들이 창문에 신문지를 붙이고 배를 뭍으로 끌어올리고 있었다.", "In every alley, people were taping newspaper to windows and hauling boats up onto land." },
            { "할머니한테 인사했다. 할머니는 대답이 없었다. 라디오에서 태풍 경보만 반복됐다.", "I said hello to a grandma. She didn't answer. The radio just repeated the typhoon warning." },
            { "가게 앞, 정류장, 방파제. 다들 바빴다. 누구도 나를 아는 얼굴이 아니었다.", "The shop front, the bus stop, the seawall. Everyone was busy. Not one face knew me." },
            { "아무도 나를 찾지 않았다. 그게 제일 무서웠다.", "Nobody was looking for me. That scared me most." },
            { "「나는 누나 알아.」 꼬마가 말했다. 「어떻게 알아?」 「그냥 알아.」", "“I know you, Sis,” the kid said. “How?” “I just do.”" },
            { "꼬마는 같은 말을 두 번 했다. 그래도 그 말 하나에 다리가 조금 풀렸다.", "The kid said the same thing twice. Still, at those words my legs loosened a little." },
            { "운행이 끊긴 정류장. 꼬마가 우리가 내려온 언덕의 녹슨 탑을 가리켰다.", "A stop where the buses had stopped running. The kid pointed at the rusty tower on the hill we'd come down." },
            { "「여기서 저기까지 노을 전에 가면 누나가 이기는 거야.」 무슨 놀이냐고 물었다. 「그냥 놀이.」", "“If you get from here to there before sunset, you win.” I asked what game it was. “Just a game.”" },
            { "꼬마가 정류장 뒤에서 낡은 스케이트보드를 끌고 나왔다.", "The kid dragged an old skateboard out from behind the bus stop." },
            { "발을 올리니 몸이 먼저 균형을 잡았다. 머리는 모르는데 발이 알았다.", "I stepped on and my body found the balance first. My head didn't know, but my feet did." },
            { "해가 지기 전에 탑 아래 담요 자리에 닿았다. 꼬마가 박수를 쳤다. 「이겼다!」 나는 웃었다. 오늘 처음 웃었다.", "I reached the blanket under the tower before the sun set. The kid clapped. “You won!” I laughed. My first laugh today." },
            { "그날 밤 바람은 더 세졌다. 꼬마가 우비 자락을 벌려 내 어깨까지 덮었다. 둘이 그 밑에서 잤다.", "That night the wind got stronger. The kid spread his raincoat over my shoulders too. We slept under it together." },
            { "보드", "The Board" },
            { "이야기 · 제 2화", "Story · Episode 2" },
            { "다음 날도 정류장에서 탑까지 달렸다. 꼬마를 보드 앞에 태웠다.", "The next day I ran from the stop to the tower again. I put the kid on the front of the board." },
            { "우비 후드가 바람에 부풀었다. 「더 빨리!」 「무서우면 말해.」 「더 빨리!」", "His raincoat hood puffed up in the wind. “Faster!” “Tell me if you get scared.” “Faster!”" },
            { "돌담 사이 굽은 길에서 넘어졌다. 둘 다 무릎이 까졌다.", "We fell on a bend between stone walls. We both scraped our knees." },
            { "꼬마가 내 무릎에 침을 발랐다. 「이러면 안 아파.」 안 아프진 않았다. 그래도 웃었다.", "The kid put spit on my knee. “Now it won't hurt.” It still hurt. I laughed anyway." },
            { "탑 아래 우유 두 병이 놓여 있었다.", "Two bottles of milk sat under the tower." },
            { "꼬마가 주머니에서 분홍빛 조개껍데기를 꺼냈다. 빨간 크레파스로 그 위에 하트를 그렸다. 삐뚤었다.", "The kid took a pink shell from his pocket. He drew a heart on it in red crayon. It was crooked." },
            { "꼬마가 그 조개껍데기를 내 손에 쥐여 줬다. 「잃어버리지 마.」", "The kid pressed the shell into my hand. “Don't lose it.”" },
            { "돌아오는 길, 꼬마가 내 손을 잡았다. 작고 차가운 손. 「내일도 가자.」 「응. 내일도.」", "On the way back, the kid took my hand. Small, cold hand. “Let's go tomorrow too.” “Yeah. Tomorrow too.”" },
            { "사진 속 얼굴", "The Face in the Photo" },
            { "가게에서 우유를 집었다. 주인 할머니는 라디오만 듣고 있었다. 「저기요.」", "I picked up milk at the shop. The old owner was only listening to the radio. “Excuse me.”" },
            { "두 번 불렀다. 할머니는 고개를 안 들었다.", "I called twice. She didn't look up." },
            { "밖에서 아저씨와 부딪혔다. 아저씨는 내 옆을 그냥 지나갔다. 「죄송해요」도 없었다. 나는 길가로 비켜섰다.", "Outside I bumped into a man. He just walked past me. Not even “sorry.” I stepped aside to the roadside." },
            { "꼬마한테 물었다. 「왜 아무도 나를 안 봐?」 꼬마는 대답 대신 발끝으로 돌멩이를 찼다.", "I asked the kid, “Why doesn't anyone look at me?” Instead of answering, he kicked a pebble with his toe." },
            { "「누나, 배고파.」 「대답해.」 「배고파.」 꼬마는 같은 말을 두 번 했다. 나는 더 못 물었다.", "“Sis, I'm hungry.” “Answer me.” “I'm hungry.” He said the same thing twice. I couldn't ask again." },
            { "초소 앞. 아줌마가 전단지를 돌리고 있었다. 지나가는 사람마다 한 장씩.", "In front of the guard post, a woman was handing out flyers. One to everyone who passed." },
            { "받는 사람은 적었다. 아줌마는 말 대신 고개를 숙였다. 소리가 하나도 없었다.", "Few took one. Instead of words, she bowed her head. There was no sound at all." },
            { "아줌마가 내 앞에도 섰다. 잠깐 나를 보더니 전단지를 내밀었다. 나는 받았다.", "She stopped in front of me too. She looked at me a moment, then held out a flyer. I took it." },
            { "어디서 본 얼굴이었다. 슬퍼 보였다. 아줌마는 고개를 숙이고 다음 사람에게 갔다.", "A face I'd seen somewhere. She looked sad. She bowed her head and moved on to the next person." },
            { "전단지를 봤다. 여자애 사진. 「고하늘, 19세, 실종.」 나는 사진을 한참 봤다. 웃지 않는 얼굴이었다.", "I looked at the flyer. A girl's photo. “Ko Haneul, 19, missing.” I looked at it a long time. A face that wasn't smiling." },
            { "꼬마가 전단지를 접어 자기 우비 주머니에 넣었다. 「내가 갖고 있을게.」 후드를 더 눌러썼다.", "The kid folded the flyer into his raincoat pocket. “I'll keep it.” He pulled his hood lower." },
            { "정류장에 키 큰 남자가 있었다. 흰 셔츠. 우유 두 병. 남자가 나를 보고 고개를 살짝 숙였다. 「안녕하세요.」", "A tall man at the bus stop. White shirt. Two bottles of milk. He saw me and gave a small bow. “Hello.”" },
            { "나도 「안녕하세요」 했다. 남자는 버스가 안 오는 정류장에 그냥 서 있었다. 뭘 기다리는지 몰랐다.", "I said “Hello” too. He just stood at a stop where no bus came. I didn't know what he was waiting for." },
            { "남자가 입을 막고 오래 기침했다. 입술이 파랬다. 기침이 끝나자 다시 정류장에 섰다.", "The man covered his mouth and coughed a long time. His lips were blue. When it stopped, he stood at the stop again." },
            { "밤에 가게 유리창에 얼굴을 비춰 봤다. 낮에 본 전단지 얼굴이 떠올랐다.", "At night I looked at my face in the shop window. The face on the flyer came back to me." },
            { "꼬마가 옆에 와서 유리를 보더니 손바닥으로 김을 닦았다. 「누나, 자자.」 「응.」 탑 아래 담요로 돌아갔다.", "The kid came, looked, and wiped the fog off with his palm. “Sis, let's sleep.” “Okay.” Back to the blanket under the tower." },
            { "물장구", "Splashing" },
            { "이야기 · 제 4화", "Story · Episode 4" },
            { "여름. 나는 방파제에 앉아 바다만 봤다. 며칠째 그랬다.", "Summer. I sat on the seawall and just looked at the sea. I'd been doing it for days." },
            { "꼬마가 내 앞에서 얕은 물로 첨벙 들어갔다. 우비를 입은 채로. 「누나, 봐 봐.」", "Right in front of me the kid splashed into the shallows. Raincoat and all. “Sis, look!”" },
            { "물을 튀기고, 넘어지고, 다시 튀겼다. 물에 뜬 주황색이 웃었다. 나도 신을 벗고 들어갔다.", "He splashed, fell, splashed again. The orange floating in the water laughed. I took off my shoes and went in too." },
            { "「우비 안 벗어?」 「엄마가 벗지 말랬어.」 「엄마는 어디 있어?」 「뭍에.」 꼬마가 물을 끼얹었다.", "“Not taking off your raincoat?” “Mom said not to.” “Where's your mom?” “On the mainland.” He splashed me." },
            { "모래에 둘이 누워 숨을 골랐다. 꼬마가 왼쪽 눈을 접으며 웃었다. 나도 웃었다.", "We lay on the sand catching our breath. The kid laughed with his left eye scrunched shut. I laughed too." },
            { "해가 지도록 놀았다. 배가 고팠다. 젖은 채로 방파제에 앉아 있는데 해녀복을 입은 아줌마가 지나가다 멈췄다.", "We played till sunset. I got hungry. I was sitting soaked on the seawall when a woman in a diving suit walked by and stopped." },
            { "초소 앞에서 본 아줌마였다. 아줌마는 나를 한참 보더니 내 손을 잡았다. 그리고 언덕 쪽을 가리켰다.", "The woman from the guard post. She looked at me a long time, then took my hand. And pointed up the hill." },
            { "꼬마가 내 다른 손을 잡았다. 셋이 언덕을 올라갔다.", "The kid took my other hand. The three of us climbed the hill." },
            { "밥", "A Meal" },
            { "언덕 위 외딴집. 마당에 해녀복이 널려 있었다. 아줌마가 마루에 나를 앉히고 수건을 건넸다.", "A lone house on the hill. Diving suits hung in the yard. She sat me on the porch and handed me a towel." },
            { "아줌마가 종이에 글씨를 썼다. 「밥 먹었어?」 나는 고개를 저었다.", "She wrote on paper. “Have you eaten?” I shook my head." },
            { "「말 못 해요?」 입 모양을 크게 해서 물었다. 아줌마가 고개를 끄덕였다. 「듣는 것도?」 또 끄덕였다.", "“You can't speak?” I asked, shaping the words big. She nodded. “Or hear?” She nodded again." },
            { "아줌마가 종이에 썼다. 「이름이 뭐야?」", "She wrote on the paper. “What's your name?”" },
            { "나는 펜을 들었다. 쓸 게 없었다. 「모르겠어요.」 아줌마가 내 글씨를 한참 봤다. 그리고 더 묻지 않았다.", "I picked up the pen. There was nothing to write. “I don't know.” She looked at my writing a long time. And asked no more." },
            { "부엌에서 미역국 냄새가 났다. 아줌마가 밥상을 차렸다. 밥, 미역국, 계란말이. 계란말이가 하트 모양이었다.", "Seaweed soup smelled from the kitchen. She set the table. Rice, seaweed soup, rolled omelet. The omelet was heart-shaped." },
            { "나는 밥을 두 그릇 먹었다. 따뜻한 밥을 먹어 본 게 오랜만이었다. 언제 먹었는지는 기억이 안 났다.", "I ate two bowls of rice. It had been a long time since I'd had warm food. I couldn't remember when." },
            { "아줌마가 종이에 썼다. 「딸이 집을 나갔어. 찾는 중이야.」", "She wrote on the paper. “My daughter left home. I'm looking for her.”" },
            { "「언제요?」 「봄에.」 「어디로요?」 아줌마는 펜을 놓았다.", "“When?” “In spring.” “Where to?” She put the pen down." },
            { "「그래서 매일 초소에 가는 거예요?」 끄덕. 「딸이 몇 살이에요?」 아줌마가 손가락을 폈다. 열아홉.", "“Is that why you go to the guard post every day?” A nod. “How old is she?” She held up her fingers. Nineteen." },
            { "아줌마가 내 머리를 한 번 쓰다듬었다. 그리고 썼다. 「우리 딸 같아서.」 눈물이 났다. 밥을 먹다가 울었다.", "She stroked my hair once. Then wrote, “You're like my daughter.” Tears came. I cried while eating." },
            { "아줌마가 미역국을 더 퍼 줬다. 「많이 먹어.」 그 글씨가 삐뚤었다. 나는 다 먹었다.", "She ladled me more soup. “Eat plenty.” The writing was crooked. I ate it all." },
            { "꼬마는 마루에 올라오지 않았다. 마당에 서서 창으로 나를 보고 있었다.", "The kid didn't come up onto the porch. He stood in the yard, watching me through the window." },
            { "들어오라고 손짓했다. 꼬마는 고개를 저었다. 웃는 것처럼 보였다. 그런데 슬퍼 보였다.", "I waved him in. He shook his head. He seemed to be smiling. But he looked sad." },
            { "태왁", "Taewak" },
            { "이야기 · 제 6화", "Story · Episode 6" },
            { "새벽. 아줌마가 해녀복을 입고 바다로 갔다. 나는 태왁을 들고 따라갔다. 아줌마가 손짓했다. 「여기 앉아 있어.」", "Dawn. She put on her diving suit and went to the sea. I followed with the taewak. She gestured: “Sit here.”" },
            { "바위 위에서 아줌마가 물에 들어갔다 나오는 걸 셌다. 열일곱 번. 물 위로 올라올 때마다 긴 숨소리가 났다.", "From a rock I counted her dives. Seventeen. Each time she surfaced, there was a long breath." },
            { "소리 없는 사람의 숨비소리가 바다보다 컸다. 그런데 태왁 망이 비어 있었다. 아줌마는 소라를 따지 않았다.", "The sumbisori of a woman with no voice was louder than the sea. But the taewak net was empty. She wasn't picking conch." },
            { "아줌마는 바위 틈을 하나씩 들여다봤다. 폐그물 더미를 들추고, 다시 들어가고, 다시 들췄다.", "She looked into the rock crevices one by one. Lifted piles of old net, went back down, lifted them again." },
            { "물에서 나올 때마다 손에 아무것도 없었다. 나는 무엇을 찾는지 묻지 못했다.", "Every time she came up, her hands were empty. I couldn't ask what she was looking for." },
            { "마지막에 아줌마가 물에서 나와 내 무릎에 소라를 하나 올려놨다. 「너 거.」", "At the end she came out and set one conch on my knee. “Yours.”" },
            { "손짓이었다. 손이 차가웠다. 나는 아줌마 손을 두 손으로 감쌌다. 아줌마가 웃었다.", "It was a gesture. Her hand was cold. I wrapped both my hands around it. She smiled." },
            { "저녁에 아줌마가 내 머리를 땋아 줬다. 마루 끝에 꼬마가 앉아 그걸 보고 있었다.", "In the evening she braided my hair. The kid sat at the end of the porch, watching." },
            { "웃는 것처럼 보였다. 그런데 슬퍼 보였다.", "He seemed to be smiling. But he looked sad." },
            { "언덕 위 집", "The House on the Hill" },
            { "아줌마 집에 매일 갔다. 아줌마는 매일 밥을 했다. 나는 설거지를 했다. 손이 시리도록 찬물이었다. 좋았다.", "I went to her house every day. She cooked every day. I washed the dishes. The water was cold enough to sting. I liked it." },
            { "아줌마가 빨래를 걷었다. 크기가 다른 해녀복 두 벌.", "She took in the laundry. Two diving suits, different sizes." },
            { "작은 쪽은 아무도 안 입었다. 아줌마는 그걸 매일 걷고 매일 다시 널었다.", "Nobody wore the small one. She took it in every day and hung it out again every day." },
            { "저녁에 아줌마가 사진을 꺼내 보여 줬다. 열아홉 살 여자애.", "In the evening she took out a photo to show me. A nineteen-year-old girl." },
            { "나는 사진을 봤다. 「예쁘네요.」 아줌마가 웃었다. 그리고 사진을 다시 품에 넣었다.", "I looked at the photo. “She's pretty.” She smiled. Then tucked the photo back inside her shirt." },
            { "아줌마가 내 손을 잡고 마당의 작은 텃밭으로 갔다. 손짓으로 알려 줬다.", "She took my hand and led me to the little vegetable patch in the yard. She showed me with gestures." },
            { "이건 파, 이건 상추. 나는 따라 했다. 손에 흙이 묻었다.", "This is green onion, this is lettuce. I copied her. Dirt got on my hands." },
            { "비 오는 날 마루에서 둘이 나란히 앉아 있었다.", "On a rainy day we sat side by side on the porch." },
            { "아줌마가 내 어깨에 담요를 덮어 줬다. 아무 말도 없었다. 빗소리만으로 충분했다.", "She put a blanket over my shoulders. No words. The sound of the rain was enough." },
            { "부엌 벽 달력에 동그라미가 하나 있었다. 내년 봄 어느 날. 손가락으로 가리키며 물었다.", "On the kitchen calendar there was one circle. A day next spring. I pointed at it and asked." },
            { "아줌마가 종이에 썼다. 「딸 생일.」 그리고 「미역국 끓여야지」 하고 썼다. 나는 그 동그라미를 오래 봤다.", "She wrote, “Daughter's birthday.” Then, “I'll make seaweed soup.” I looked at that circle a long time." },
            { "그날 밤 처음으로 담요가 아닌 데서 잤다. 그 집 작은 방. 벽에 낡은 주황 우비가 걸려 있었다. 어른 것이었다.", "That night I first slept off the blanket. Her small room. An old orange raincoat hung on the wall. An adult's." },
            { "창밖에서 꼬마가 우비를 올려다보고 있었다. 나와 눈이 마주쳤다. 꼬마가 얼른 고개를 돌렸다. 어깨가 조금 흔들렸다.", "Outside the window the kid was looking up at the raincoat. Our eyes met. He quickly turned away. His shoulders shook a little." },
            { "아침에 언덕길에서 그 남자와 마주쳤다. 남자가 언덕 위 집을 올려다봤다.", "In the morning I ran into that man on the hill road. He looked up at the house on the hill." },
            { "오래 봤다. 그리고 「안녕하세요」 하고 지나갔다.", "He looked a long time. Then said “Hello” and walked past." },
            { "나는 남자의 뒷모습을 봤다. 아줌마도 마루에서 그 뒷모습을 봤다.", "I watched his back. From the porch, she watched it too." },
            { "사진을 꺼내려다 말았다. 남자는 그냥 갔다. 나도 방으로 들어갔다.", "She started to take out the photo, then stopped. He just left. I went back into the room too." },
            { "우유 두 병", "Two Bottles of Milk" },
            { "이야기 · 제 8화", "Story · Episode 8" },
            { "가게 앞. 그 남자가 우유 두 병을 샀다. 딸깍, 딸깍. 주인 할머니가 물었다. 「오늘도 두 개라?」 「예.」", "In front of the shop, that man bought two bottles of milk. Clink, clink. The old owner asked, “Two again today?” “Yes.”" },
            { "「요양 왔으민 고기도 먹어사주. 우유만 먹엉 어떵 살아.」 남자는 웃기만 했다.", "“Come here to get well, ya gotta eat meat too. How ya gonna live on milk?” He only smiled." },
            { "남자가 나를 보고 또 「안녕하세요」 했다. 나도 「안녕하세요」 했다. 매일 같은 자리, 같은 시간.", "He saw me and said “Hello” again. I said “Hello” too. Same spot, same time, every day." },
            { "남자와 눈이 마주쳤다. 나는 괜히 신발 끈을 다시 묶었다.", "Our eyes met. For no reason, I retied my shoelaces." },
            { "언덕길에서 아줌마가 내려오고 있었다. 나는 다가가려다 걸음을 멈췄다.", "She was coming down the hill road. I started toward her, then stopped." },
            { "아줌마는 내 쪽은 보지도 않고, 손에 든 사진만 뚫어지게 보며 스쳐 지나갔다.", "She didn't even look my way. She passed by, staring hard at the photo in her hand." },
            { "매일 나에게 따뜻한 밥을 차려 주던 얼굴인데, 사진을 보는 그 표정은 텅 비어 있었다.", "The face that set out warm food for me every day was blank as it looked at the photo." },
            { "그 지독한 슬픔 때문에 마치 처음 보는 사람 같았다.", "That terrible sadness made her seem like someone I'd never met." },
            { "남자는 우유 두 병을 들고 탑 쪽으로 갔다. 아줌마는 초소 쪽으로 갔다.", "The man took his two bottles of milk toward the tower. She went toward the guard post." },
            { "두 사람의 등이 서로 반대편으로 멀어졌다. 나는 그 사이에 서 있었다. 꼬마가 내 소매를 꽉 잡고 있었다.", "Their backs moved away in opposite directions. I stood between them. The kid was gripping my sleeve tight." },
            { "첫눈", "First Snow" },
            { "이야기 · 제 9화", "Story · Episode 9" },
            { "첫눈. 꼬마와 창가 성에에 얼굴을 그렸다. 꼬마 하나, 나 하나. 꼬마가 하나 더 그렸다. 「누구야?」 「몰라.」", "First snow. The kid and I drew faces in the window frost. One kid, one me. He drew one more. “Who's that?” “Dunno.”" },
            { "눈사람을 만들었다. 꼬마가 내 목도리를 눈사람에게 감아 줬다. 「추우니까.」 「나는?」", "We built a snowman. The kid wrapped my scarf around it. “'Cause it's cold.” “What about me?”" },
            { "「누나는 내 우비 반 줄게.」 우비 한쪽을 내 어깨에 걸쳤다. 둘 다 반만 젖었다.", "“You get half my raincoat.” He put one side over my shoulder. We both got half wet." },
            { "돌아오는 길에 꼬마가 자꾸 뒤를 돌아봤다. 「뭐 봐?」 「아무것도.」 두 번 물어도 아무것도.", "On the way back the kid kept looking behind him. “What are you looking at?” “Nothing.” Asked twice, still nothing." },
            { "꼬마가 내 무릎을 베고 잤다. 후드 아래로 왼쪽 눈가가 접혀 있었다.", "The kid fell asleep on my lap. Under his hood, the corner of his left eye was crinkled." },
            { "웃으면서 자는 애였다. 나는 후드 위로 머리를 한 번 만졌다. 손바닥이 따뜻했다.", "He was a kid who smiled in his sleep. I touched his head once through the hood. My palm was warm." },
            { "파란 머리띠", "The Blue Headband" },
            { "봄. 아줌마 집 장롱 깊은 데서 노란 통이 나왔다. 뚜껑에 붉은 하트. 아줌마는 집에 없었다.", "Spring. Deep in her wardrobe I found a yellow tin. A red heart on the lid. She wasn't home." },
            { "뚜껑을 열었다. 파란 보석 머리띠. 한 번도 안 쓴 새것이었다.", "I opened the lid. A headband with blue jewels. Brand new, never worn." },
            { "머리띠를 집는 순간, 머리가 깨질 듯 아팠다. 기억이 한꺼번에 밀고 들어왔다. 그런데 이상했다.", "The moment I picked up the headband, my head felt like it would split. Memories pushed in all at once. But it was strange." },
            { "엄마 얼굴만 안 보였다. 손과 해녀복과 숨소리만 돌아왔다.", "Only Mom's face was missing. Only her hands, her diving suit and her breathing came back." },
            { "처음 가 본 시내 백화점. 유리 안에 파란 보석 머리띠가 있었다. 나는 오래 봤다. 갖고 싶다는 말은 안 했다.", "A department store in town, my first time there. Behind glass, a headband with blue jewels. I looked a long time. I never said I wanted it." },
            { "— 회상 · 열한 살 —", "— Flashback · Age eleven —" },
            { "그 말이 사치라는 건 열한 살도 알았다. 유리에 손자국만 남기고 돌아섰는데, 아빠가 그 손자국을 보고 있었다.", "Even at eleven I knew saying it would be a luxury. I turned away, leaving only handprints on the glass, and Dad was looking at those handprints." },
            { "— 회상 —", "— Flashback —" },
            { "그을린 얼굴, 낡은 점퍼. 아빠가 웃었다. 왼쪽 눈이 접혔다. 「하늘이 생일 선물이 정해졌주.」", "A sunburnt face, a worn jacket. Dad smiled. His left eye creased. “Haneul's birthday present's all settled, then.”" },
            { "아빠는 내 물건마다 빨간 페인트로 하트를 그려 줬다. 가방에도, 신발에도. 삐뚤었다.", "Dad painted a red heart on everything of mine. On my bag, on my shoes. They were crooked." },
            { "「잃어버리지 말라.」 아빠 주황 우비 소매에도 같은 하트가 있었다.", "“Don't go losing it.” The sleeve of Dad's orange raincoat had the same heart." },
            { "해녀 엄마, 배 한 척뿐인 아빠. 머리띠 값은 아빠 한 달 벌이였다.", "A haenyeo mom, a dad with just one boat. The headband cost a month of Dad's earnings." },
            { "아빠는 이웃에게 돈을 빌려 머리띠를 사 왔고, 빌린 돈을 갚으려면 풍랑주의보가 내린 밤에도 바다에 나가야 했다.", "Dad borrowed from a neighbor to buy the headband. To pay it back, he had to go out to sea even on a storm-warning night." },
            { "아빠가 장화를 신었다. 엄마가 아빠 우비를 낚아챘다. 소리는 없었다. 엄마 손이 빠르게 허공을 갈랐다.", "Dad pulled on his boots. Mom snatched Dad's raincoat. There was no sound. Mom's hands cut fast through the air." },
            { "가지 마. 엄마 얼굴이 어땠는지는 떠오르지 않는다. 그 손만 떠오른다. 아빠는 그 손을 안 봤다.", "Don't go. I can't recall what Mom's face was like. Only those hands. Dad didn't look at those hands." },
            { "나는 대문턱에서 아빠 소매를 두 손으로 잡았다. 「아빠, 생일 안 해도 돼.」 아빠가 내 머리를 한 번 만졌다.", "At the doorsill I held Dad's sleeve with both hands. “Dad, I don't need a birthday.” Dad touched my head once." },
            { "「한 마리만 더 잡으민 뒈어, 하늘아.」 하트가 그려진 소매가 손에서 빠져나갔다.", "“Just one more catch'll do it, Haneul.” The sleeve with the heart slipped out of my hands." },
            { "젖은 소매의 감촉이 아직도 손에 있다.", "I can still feel the wet sleeve in my hands." },
            { "거짓말처럼 맑은 아침이었다. 사람들이 바다로 뛰었다.", "It was a morning clear as a lie. People ran to the sea." },
            { "— 회상 · 다음 날 —", "— Flashback · The next day —" },
            { "엄마가 나를 방에 넣고 문을 닫았다. 문틈으로 주황색이 한 번 지나갔다.", "Mom put me in my room and shut the door. Through the crack, orange went by once." },
            { "송전탑 아래 바다에 아빠 배가 뒤집혀 있었고, 삐뚤어진 하트가 그려진 부표 하나만 떠 있었다.", "In the sea under the tower, Dad's boat lay upside down, and only one buoy floated, painted with a crooked heart." },
            { "아빠는 돌아오지 않았다. 나는 울지 않았다. 울면 진짜가 될 것 같았다.", "Dad didn't come back. I didn't cry. If I cried, it felt like it would become real." },
            { "엄마는 그날 노란 통을 열어 보지도 않고 장롱 깊은 데 넣었다. 그날부터 우리 집엔 생일이 없어졌다.", "That day Mom put the yellow box deep in the wardrobe without even opening it. From that day, our house had no birthdays." },
            { "아빠가 죽은 뒤, 우리 집은 완전히 소리가 사라졌다. 학교에서는 매일 같은 일이 있었다. 「생선 냄새 나.」", "After Dad died, all sound left our house. At school the same thing happened every day. “You smell like fish.”" },
            { "「벙어리 딸.」 아이들이 도시락을 개수대에 붓고, 가방을 도랑에 던지고, 입만 뻐끔거리며 엄마 흉내를 냈다.", "“Mute's daughter.” Kids dumped my lunch in the sink, threw my bag in the ditch, and mouthed silently, mimicking Mom." },
            { "나는 매일 못 들은 척했다. 엄마처럼. 집에 와서도 엄마한테 아무 말도 안 했다.", "Every day I pretended not to hear. Like Mom. At home I didn't say anything to Mom either." },
            { "말해도 못 들으니까. 말할 사람이 없었다. 그게 제일 외로웠다.", "She couldn't hear it anyway. There was no one to tell. That was the loneliest part." },
            { "흰 셔츠", "The White Shirt" },
            { "이야기 · 제 11화", "Story · Episode 11" },
            { "전학생이 왔다. 서울에서. 몸이 아파서 요양하러 제주에 왔다고 했다.", "A transfer student came. From Seoul. They said he'd come to Jeju to recover because he was sick." },
            { "— 회상 · 열두 살 봄 —", "— Flashback · Spring, age twelve —" },
            { "흰 셔츠가 눈부셨고, 얼굴은 셔츠만큼 하얬다. 아이들이 그 애를 둘러쌌고 나는 늘 그렇듯 구석에 있었다.", "His white shirt was dazzling, and his face was as white as the shirt. The kids crowded around him, and I was in the corner as always." },
            { "가방이 또 도랑에 던져진 날, 그 애가 도랑에 들어갔다. 흰 셔츠가 진흙투성이가 되도록 가방을 건져 왔다.", "The day my bag got thrown in the ditch again, he climbed into the ditch. He fished my bag out till his white shirt was covered in mud." },
            { "아이들이 그 애도 밀었다. 그 애는 넘어졌다. 다시 일어나서 내 앞에 섰다. 손이 떨리는 걸 나만 봤다.", "The kids shoved him too. He fell. He got back up and stood in front of me. Only I saw his hands shaking." },
            { "「싸움도 못하면서 왜 앞을 막아?」 「네가 뒤에 있으니까.」", "“You can't even fight. Why stand in front?” “Because you're behind me.”" },
            { "그 애는 운동장 구석에 앉아 도시락을 열고 한가운데 선을 그었다. 「반은 네 거.」 계란말이가 따뜻했다.", "He sat in a corner of the schoolyard, opened his lunchbox, and drew a line down the middle. “Half is yours.” The rolled omelet was warm." },
            { "나는 그날 처음으로 학교에서 밥을 먹었다. 그 애 이름은 도윤이었다. 도윤이 얼굴은 기억난다. 그 애만은.", "That day I ate at school for the first time. His name was Doyun. I remember Doyun's face. His, at least." },
            { "우리 기지", "Our Hideout" },
            { "그해 봄, 도윤이와 나는 매일 바다에서 놀았다. 도윤이는 서울 애라 수영을 못 했다.", "That spring, Doyun and I played at the sea every day. Doyun was a Seoul kid, so he couldn't swim." },
            { "나는 얕은 물에서 수영을 가르쳤다. 도윤이는 물을 먹고, 기침을 하고, 다시 들어왔다.", "I taught him to swim in the shallows. Doyun swallowed water, coughed, and went back in." },
            { "해가 지면 방파제에 나란히 앉아 젖은 옷을 말렸다. 그전까지 나는 웃는 법을 잊고 있었다.", "At sunset we sat side by side on the breakwater, drying our wet clothes. Until then I had forgotten how to laugh." },
            { "그 봄에 소리 내서 웃었다. 「너 웃을 줄 아네.」 「시끄러워.」", "That spring I laughed out loud. “So you can laugh.” “Shut up.”" },
            { "도윤이가 바닷가 바위 틈의 버려진 해녀 불턱을 기지로 꾸몄다.", "Doyun made an abandoned haenyeo bulteok, a stone shelter in the seaside rocks, into our hideout." },
            { "돌담 안에 담요를 깔고, 고장 난 라디오를 가져다 놓고, 우유를 두 병씩 숨겨 뒀다.", "Inside the stone wall we spread a blanket, brought a broken radio, and hid milk, two bottles at a time." },
            { "「여긴 우리 기지야.」 라디오를 같이 뜯다가 89.2에서 희미하게 노래가 잡혔다.", "“This is our hideout.” We took the radio apart together, and at 89.2 a song came in faintly." },
            { "도윤이가 다이얼 옆에 하트를 그렸다. 「이 주파수는 우리 거야.」", "Doyun drew a heart next to the dial. “This frequency is ours.”" },
            { "기지까지는 방파제 길을 보드로 달렸다. 도윤이는 뒤에서 헐떡이며 따라왔다.", "I rode my board along the breakwater to the hideout. Doyun followed behind, panting." },
            { "기지에 들어가니 촛불이 켜져 있었다. 초 열두 개. 도윤이가 케이크 뒤에서 튀어나왔다.", "Inside the hideout, candles were lit. Twelve of them. Doyun jumped out from behind a cake." },
            { "— 회상 · 열두 살 생일 —", "— Flashback · Twelfth birthday —" },
            { "「깜짝 선물!」 나는 웃었다. 촛불을 끄고, 케이크를 반씩 먹었다.", "“Surprise!” I laughed. I blew out the candles, and we ate half the cake each." },
            { "해가 기울자 도윤이가 내 손을 끌었다. 「나머지는 송전탑 가서 먹자. 거기서 노을이 제일 예뻐.」", "As the sun sank, Doyun tugged my hand. “Let's eat the rest at the tower. The sunset's prettiest there.”" },
            { "손을 뿌리쳤다. 「거기 가자는 말 하지 마.」 「왜? 딱 한 번만.」 「싫다고!」", "I shook off his hand. “Don't ask me to go there.” “Why? Just once.” “I said no!”" },
            { "케이크 접시가 바위에 떨어졌다. 「모르면서 왜 자꾸 끼어들어!」 도윤이는 한참 나를 봤다.", "The cake plate fell on the rock. “You don't know anything, so why do you keep butting in!” Doyun looked at me a long time." },
            { "「……미안.」 그리고 갔다. 나는 엎어진 케이크 앞에 혼자 남았다. 촛농이 바위 위에서 식어 갔다.", "“……Sorry.” And he left. I stayed alone in front of the upturned cake. Candle wax cooled on the rock." },
            { "열흘 동안 도윤이는 오지 않았다. 대신 담장 위에 매일 도시락이 놓였다. 첫날은 따뜻했고 열흘째엔 식어 있었다.", "For ten days Doyun didn't come. Instead, a lunchbox was left on the wall every day. The first was warm; the tenth was cold." },
            { "마지막 도시락 뚜껑 안에 글씨가 있었다. 「친구 아니어도 반은 네 거.」 그날 밤 도윤이 집 앞을 지나갔다.", "Inside the last lunchbox lid, writing: “Even if we're not friends, half is yours.” That night I passed Doyun's house." },
            { "창가에 도윤이가 앉아 송전탑 쪽을 보고 있었다. 오래. 방 벽에 그림이 붙어 있었다.", "Doyun sat at the window, looking toward the tower. For a long time. A drawing was stuck on his wall." },
            { "송전탑, 노을, 그 아래 케이크를 든 둘. 나는 담 밑에서 그걸 보고 올라가지 못했다.", "The tower, a sunset, two people beneath it holding a cake. I saw it from below the wall and couldn't go up." },
            { "태풍", "Typhoon" },
            { "이야기 · 제 13화", "Story · Episode 13" },
            { "그 뒤로 도윤이와 나는 말을 하지 않았다. 학교 복도에서 도윤이가 먼저 다가왔다. 「하늘아, 그날……」", "After that, Doyun and I didn't speak. In the school hallway, Doyun came up to me first. “Haneul, that day……”" },
            { "— 회상 · 여름 끝 —", "— Flashback · End of summer —" },
            { "「됐어. 다시는 말 걸지 마.」 도윤이는 입을 다물었다. 다음 날부터 담장 위에 도시락이 놓이지 않았다.", "“Forget it. Don't ever talk to me again.” Doyun shut his mouth. From the next day, no lunchbox was left on the wall." },
            { "혼자 기지에 가 봤다. 담요는 비에 젖어 있었고, 라디오는 꺼져 있었다. 나는 켜지 않고 돌아왔다.", "I went to the hideout alone. The blanket was soaked with rain, and the radio was off. I came back without turning it on." },
            { "비가 앞이 안 보이게 쏟아졌다. 양철 지붕이 쉬지 않고 울렸다. 전화가 끊기고 전기도 나갔다.", "Rain poured so hard I couldn't see ahead. The tin roof rang without stopping. The phone cut out, and the power went too." },
            { "— 회상 · 여름 태풍 —", "— Flashback · Summer typhoon —" },
            { "촛불을 켰는데 마당에서 소리가 났다. 엄마가 엎어져 있었다. 가슴을 움켜쥐고.", "I lit a candle, and there was a sound in the yard. Mom was lying face down. Clutching her chest." },
            { "해녀들이 걸리는 심장병이었다. 엄마 얼굴은 이번에도 안 보인다. 젖은 해녀복과 가슴을 쥔 손만 보인다.", "It was the heart disease haenyeo get. Again I can't see Mom's face. Only a wet diving suit and a hand gripping her chest." },
            { "우리 집은 언덕 위 외딴집이었다. 제일 가까운 집까지 30분, 병원까지 2킬로. 빗속에 길이 안 보였다.", "Our house stood alone on the hill. Thirty minutes to the nearest house, 2 km to the hospital. I couldn't see the road in the rain." },
            { "「엄마! 엄마!」 나는 울부짖었다. 엄마는 못 듣는다. 알면서도 불렀다. 부르는 것밖에 할 게 없었다.", "“Mom! Mom!” I screamed. Mom can't hear. I knew, and I called anyway. Calling was all I could do." },
            { "마당 끝까지 뛰어가 소리를 질렀다. 「누가 좀 도와주세요!」 빗소리가 내 목소리를 삼켰다. 아무도 없었다.", "I ran to the edge of the yard and shouted. “Somebody help!” The rain swallowed my voice. There was no one." },
            { "엄마 손이 점점 차가워졌다. 나는 엄마를 안고 울었다. 열두 살이었다. 할 수 있는 게 아무것도 없었다.", "Mom's hand grew colder and colder. I held Mom and cried. I was twelve. There was nothing I could do." },
            { "리어카", "The Handcart" },
            { "이야기 · 제 14화", "Story · Episode 14" },
            { "빗속에서 손전등 불빛이 올라왔다. 도윤이였다. 우비도 없이 흠뻑 젖어서. 「너 걱정돼서.」", "A flashlight beam came up through the rain. It was Doyun. Soaked, no raincoat. “I was worried about you.”" },
            { "「어떻게 왔어?」 「뛰었어.」 도윤이가 엄마를 보고 얼굴이 굳었다. 그래도 말했다.", "“How'd you get here?” “I ran.” Doyun saw Mom and his face went stiff. He spoke anyway." },
            { "「살 수 있어.」 그렇게 말해야 내가 움직이니까. 그 애도 몰랐으면서.", "“She'll live.” He had to say it so I would move. He didn't know either." },
            { "길가에 낡은 리어카가 있었다. 바퀴가 진흙에 빠져 있었다. 둘이서 끌어냈다. 손톱이 갈라졌다.", "There was an old handcart by the road. Its wheels were stuck in the mud. We dragged it out together. Our nails split." },
            { "엄마를 눕히고 도윤이 겉옷을 덮었다. 병원까지 2킬로. 도윤이가 앞에서 끌고 내가 뒤에서 밀었다.", "We laid Mom down and covered her with Doyun's jacket. 2 km to the hospital. Doyun pulled in front, I pushed from behind." },
            { "빗길에 몇 번이나 미끄러졌다. 도윤이 무릎이 꺾였다. 다시 일어났다. 「먼저 가.」", "We slipped again and again on the wet road. Doyun's knees buckled. He got back up. “Go on ahead.”" },
            { "「싫어. 셋이 같이 가.」 도윤이가 울면서 말했다. 나도 울면서 밀었다. 병원 불빛이 보였다.", "“No. The three of us go together.” Doyun said it crying. I pushed, crying too. We saw the hospital lights." },
            { "엄마는 살았다. 의사가 그렇게 말했다. 나는 복도 바닥에 주저앉았다.", "Mom lived. The doctor said so. I sank to the hallway floor." },
            { "도윤이가 옆에 앉았다. 「거봐. 살 수 있다고 했잖아.」 그 애 손이 아직 떨리고 있었다.", "Doyun sat beside me. “See? I told you she'd live.” His hands were still shaking." },
            { "스무 살 생일", "Twentieth Birthday" },
            { "이야기 · 제 15화", "Story · Episode 15" },
            { "응급실 문이 닫히자 도윤이가 복도에 쓰러졌다. 늘 입술이 파랗게 질려 있던 이유를 나는 그때 처음 알았다.", "When the ER doors closed, Doyun collapsed in the hallway. Only then did I learn why his lips had always been blue." },
            { "다음 날 도윤이네 집 앞에 검은 차가 서 있었다. 짐이 실리고 있었다.", "The next day a black car stood in front of Doyun's house. Bags were being loaded." },
            { "「서울 병원으로 가야 한대.」 도윤이 엄마가 울면서 말했다. 「오늘.」", "“He has to go to a hospital in Seoul.” Doyun's mom said it crying. “Today.”" },
            { "나는 병원에서 엄마 곁에 있다가 그 말을 들었다. 달렸다. 병원에서 도윤이네 집까지 쉬지 않고 달렸다.", "I heard it while I was at the hospital by Mom's side. I ran. From the hospital to Doyun's house without stopping." },
            { "숨이 찼다. 그래도 달렸다. 차가 이미 출발하고 있었다. 도윤이가 뒷유리에 붙어서 나를 봤다.", "I was out of breath. I ran anyway. The car was already pulling away. Doyun was pressed to the rear window, looking at me." },
            { "창을 내렸다. 「하늘아! 스무 살 네 생일에 송전탑 아래서 보자! 꼭!」", "He rolled down the window. “Haneul! Let's meet under the tower on your twentieth birthday! Promise!”" },
            { "「우유 두 병 들고 기다릴게! 하나는 오늘, 하나는 내일!」", "“I'll wait with two bottles of milk! One for today, one for tomorrow!”" },
            { "「알았어! 안 늦을게!」 나는 차를 따라 달리다 넘어졌다. 무릎에서 피가 났다. 안 아팠다.", "“Okay! I won't be late!” I ran after the car and fell. My knee bled. It didn't hurt." },
            { "그날 밤 달력에 처음으로 글씨를 썼다. 「스무 살 생일, 송전탑 아래, 도윤이.」", "That night I wrote on the calendar for the first time. “Twentieth birthday, under the tower, Doyun.”" },
            { "연필을 꾹 눌러서 종이가 팼다. 나는 그 약속 하나로 여덟 해를 살았다.", "I pressed the pencil so hard the paper dented. I lived eight years on that one promise." },
            { "전부 알아버렸다", "Now I Know Everything" },
            { "머리띠를 든 채로 마루에 앉아 있었다. 밖이 어두워져 있었다. 나는 하늘이었다. 고하늘. 이 집 딸.", "I sat on the maru floor, still holding the headband. Outside it had gone dark. I was Haneul. Go Haneul. The daughter of this house." },
            { "마당에 아줌마가 들어왔다. 회상에서 비어 있던 엄마 얼굴에 그 얼굴이 들어갔다.", "A woman came into the yard. Her face filled the blank where Mom's face had been in the flashbacks." },
            { "많이 야윈 얼굴. 엄마였다. 사진을 품에 넣고 초소에서 돌아오는 엄마.", "A face grown very thin. It was Mom. Mom, coming back from the lookout post with a photo held to her chest." },
            { "1년 동안 매일 나를 찾으러 다닌 엄마. 딸 같다고 밥을 해 준 엄마. 나를 앞에 두고.", "Mom, who went out looking for me every day for a year. Mom, who fed me because I was like a daughter. With me right in front of her." },
            { "엄마가 나를 보고 손을 흔들었다. 모르는 애한테 하는 손짓.", "Mom saw me and waved. The kind of wave you give a kid you don't know." },
            { "나는 엄마 얼굴을 봤다. 이제 알았다. 아는데, 엄마는 나를 몰랐다.", "I looked at Mom's face. Now I knew. I knew, but Mom didn't know me." },
            { "가게 앞으로 달렸다. 멀리 방파제 끝에 흰 셔츠가 보였다. 우유 두 병. 도윤이었다.", "I ran to the front of the store. Far off, at the end of the breakwater, a white shirt. Two bottles of milk. It was Doyun." },
            { "매일 「안녕하세요」 하던 사람.", "The man who said “Hello” to me every day." },
            { "「도윤아!」 불렀다. 바람이 소리를 삼켰다. 도윤이는 돌아보지 않았다. 흰 셔츠가 점점 작아졌다.", "“Doyun!” I called. The wind swallowed the sound. Doyun didn't look back. The white shirt grew smaller and smaller." },
            { "꼬마가 뒤에 서 있었다. 주황 우비. 소매 끝에 빨간 하트가 삐뚤게 그려져 있었다.", "The kid was standing behind me. Orange raincoat. At the end of the sleeve, a red heart, drawn crooked." },
            { "주머니 속 조개껍데기를 꺼냈다. 같은 하트였다.", "I took the seashell out of my pocket. The same heart." },
            { "꼬마가 후드를 벗었다. 웃었다. 왼쪽 눈이 접혔다.", "The kid pushed back his hood. He smiled. His left eye creased." },
            { "「……아빠?」 「한 마리만 더 잡으민 뒈어, 하늘아.」", "“……Dad?” “Just one more catch'll do it, Haneul.”" },
            { "나는 주저앉았다. 「늦게 와서 미안.」", "I sank down. “Sorry I came so late.”" },
            { "마지막 기억이 돌아왔다. 열아홉 생일. 엄마는 가슴이 아파 육지 병원에 가 있었다.", "The last memory came back. My nineteenth birthday. Mom's chest had been hurting; she was at a hospital on the mainland." },
            { "나는 혼자 엄마 해녀복을 입고 물에 들어갔다. 물이 차가웠다. 폐그물이 발목을 감았다.", "I put on Mom's diving suit alone and went into the water. The water was cold. An old fishing net wrapped around my ankle." },
            { "수면이 점점 멀어졌다. 아무도 없었다. 그 뒤는 없다.", "The surface got farther and farther away. No one was there. After that, there's nothing." },
            { "죽은 사람은 산 사람 얼굴부터 잊어버린다. 나는 살아 돌아온 게 아니었다.", "The dead forget the faces of the living first. I hadn't come back alive." },
            { "손을 봤다. 손끝이 흐려지고 있었다. 꼬마가 내 손을 잡았다.", "I looked at my hands. My fingertips were fading. The kid took my hand." },
            { "「기억을 다 찾으면 우리 딸이 떠나야 하니까. 그래서 아빠가 모른 척했어.」", "“Once you found all your memories, my girl would have to leave. So Dad pretended not to know.”" },
            { "「그럼 왜 그 집에 가는 걸 안 말렸어.」", "“Then why didn't you stop me from going to that house?”" },
            { "「우리 딸이 엄마를 못 알아봐도, 엄마 밥은 먹었으면 해서.」 꼬마가 울었다. 아빠가 울었다.", "“Even if my girl couldn't recognize her mom, I wanted her to eat her mom's cooking.” The kid cried. Dad cried." },
            { "나는 유리창을 봤다. 사진 속 그 얼굴이 거기 있었다. 열아홉의 나.", "I looked at the window. The face from the photo was there. Me at nineteen." },
            { "이제야 나로 보였다. 다른 사람들 눈엔 끝까지 다른 사람이었을 얼굴.", "Only now did it look like me. A face that, to everyone else, would have been someone else to the end." },
            { "안을 수 없는", "Too Far to Hold" },
            { "이야기 · 제 19화", "Story · Episode 19" },
            { "언덕 위 집으로 달렸다. 엄마가 부엌에서 미역국을 끓이고 있었다.", "I ran to the house on the hill. Mom was making seaweed soup in the kitchen." },
            { "벽에 걸린 달력의 동그라미가 내일이었다. 딸 생일. 내 생일.", "The circle on the wall calendar was tomorrow. Her daughter's birthday. My birthday." },
            { "「엄마.」 엄마는 못 듣는다. 나는 엄마 앞에 서서 입 모양으로 말했다.", "“Mom.” Mom can't hear. I stood in front of her and shaped the words with my mouth." },
            { "「엄마, 나야. 하늘이.」 엄마는 국자만 저었다. 내 쪽으로 고개를 들지 않았다.", "“Mom, it's me. Haneul.” Mom just stirred with the ladle. She didn't lift her head toward me." },
            { "엄마를 안았다. 두 팔이 엄마 어깨를 통과했다.", "I hugged Mom. My arms passed through her shoulders." },
            { "품 안에 찬 공기뿐이었다. 다시 안았다. 또 통과했다. 엄마는 춥다는 듯 옷깃을 여몄다.", "Only cold air in my arms. I hugged her again. Through again. Mom pulled her collar closed, as if she were cold." },
            { "엄마가 국을 두 그릇 펐다. 빈 마루를 둘러보더니, 작은 방 문을 열어 봤다.", "Mom ladled out two bowls of soup. She looked around the empty maru, then opened the door to the small room." },
            { "종이에 「밥 먹자」라고 써서 마루에 올려놓았다.", "She wrote “Let's eat” on a piece of paper and set it on the maru." },
            { "그러고는 대문 밖으로 나가 언덕 아래를 한참이나 서성였다. 나는 엄마 바로 뒤에 서 있었다.", "Then she went out the gate and paced, looking down the hill, for a long time. I stood right behind her." },
            { "엄마 옆에 앉아 미역국이 끓는 걸 봤다. 먹을 수 없다는 걸 알면서.", "I sat next to Mom and watched the seaweed soup boil. Knowing I couldn't eat it." },
            { "그동안 이 엄마가 해 준 밥을 먹었다. 그걸로 됐다고, 그렇게 생각하려고 했다. 안 됐다. 안고 싶었다.", "All this time I had eaten the meals this mom made. I tried to think that was enough. It wasn't. I wanted to hold her." },
            { "송전탑 아래", "Under the Tower" },
            { "스무 살 생일. 노을이 탑 아래로 내려앉았다. 도윤이가 우유 두 병을 들고 서 있었다. 여덟 해 만의 약속 자리에.", "Twentieth birthday. The sunset settled under the tower. Doyun stood holding two bottles of milk. At the promised place, after eight years." },
            { "나는 늦지 않았다. 도윤이 앞에 섰다. 「나 왔어.」 도윤이는 내 어깨 너머 언덕길만 봤다.", "I wasn't late. I stood in front of Doyun. “I'm here.” Doyun only looked past my shoulder, at the hill road." },
            { "「5분 지나면 화낼 거야.」 도윤이가 애써 웃으며 혼잣말을 했다.", "“If you're five minutes late, I'll be mad.” Doyun forced a smile and said it to himself." },
            { "「10분 지나면 더 오래 기다릴 거야. 그러니까 빨리 와.」 나는 바로 앞에 있었다.", "“If it's ten minutes, I'll wait even longer. So hurry up.” I was right in front of him." },
            { "그때 엄마가 언덕을 올라왔다. 품에 흰 국화를 안고 있었다. 걸음이 휘청거렸다.", "Then Mom came up the hill. She held white chrysanthemums in her arms. Her steps wobbled." },
            { "엄마는 초소에서 받은 팩스 종이를 도윤이에게 내밀었다. 『오늘 새벽. 탑 남쪽 폐그물 아래. 시신 인양.』", "Mom held out to Doyun the fax she'd gotten at the guard post. ‘Early this morning. Under the ghost nets south of the tower. Body recovered.’" },
            { "종이를 읽은 도윤이가 우유 두 병을 끌어안은 채 바닥으로 무너졌다.", "Doyun read the paper and crumpled to the ground, clutching the two bottles of milk." },
            { "「하나는 오늘, 하나는 내일이라며……. 내일 건 누가 마셔.」", "“You said one for today, one for tomorrow…… Who drinks tomorrow's?”" },
            { "엄마는 소리 내어 울지 못했다. 무너진 도윤이의 등을 껴안고 짐승처럼 헐떡이며 눈물만 쏟았다.", "Mom couldn't cry out loud. She held the collapsed Doyun's back, gasping like an animal, only tears pouring." },
            { "그 종이를 본 순간, 내 발끝이 투명해지기 시작했다. 바다 밑에 묶여 있던 내 몸이 드디어 뭍으로 올라온 것이다.", "The moment I saw that paper, my toes began to turn clear. My body, held under the sea, had finally come ashore." },
            { "이승에 남겨뒀던 마지막 미련이 풀리자, 머물 수 있는 시간도 끝이 났다.", "When the last thing holding me to this world came loose, my time to stay ran out too." },
            { "꼬마가 내 옆에 섰다. 주황 우비를 벗어 바닥에 내려놓았다. 「아빠.」 「응.」", "The kid stood beside me. He took off the orange raincoat and laid it on the ground. “Dad.” “Yeah.”" },
            { "「나 이제 가나 봐.」 「응. 바닷물 찼지. 이제 춥지 않은 데로 가, 우리 딸.」", "“I guess I'm going now.” “Yeah. The seawater was cold. Go somewhere that isn't cold now, my girl.”" },
            { "「아빠, 무서워.」 「괜찮아. 아빠가 여기서 보고 있을게. 1년 동안 하늘이 혼자 안 둬서 다행이다.」", "“Dad, I'm scared.” “It's okay. Dad will be watching from here. Glad I didn't leave Haneul alone for that year.”" },
            { "멀리서 「민재야!」 부르는 소리가 들렸다. 뭍 말씨였다. 유채밭 사이로 한 여자가 달려오고 있었다.", "From far off came a call: “Minjae!” A mainland accent. A woman was running through the canola field." },
            { "여자의 손에 다 해진 전단지. 『민재를 찾습니다.』 전화번호 앞자리가 뭍 것이었다. 날짜는 작년 봄.", "In her hand, a worn-out flyer. ‘Looking for Minjae.’ The phone number had a mainland area code. The date: last spring." },
            { "아빠가 나를 보고 웃었다. 왼쪽 눈이 접히는, 내가 가장 사랑했던 얼굴.", "Dad looked at me and smiled. His left eye creased — the face I loved most." },
            { "눈을 깜빡이는 순간, 그 웃음이 지워졌다. 나를 보는 꼬마의 눈에 더 이상 아빠는 없었다.", "In a blink, that smile was gone. Dad was no longer in the kid's eyes looking at me." },
            { "그 시선은 나를 완전히 잃어버린 채, 유채밭 쪽만 멍하니 향해 있었다.", "His eyes had lost me completely. They just stared blankly toward the canola field." },
            { "「엄마한테 가.」 내 말에 꼬마는 뒤도 돌아보지 않고 유채밭으로 뛰어갔다.", "“Go to your mom.” At my words the kid ran into the canola field without looking back." },
            { "아빠를 두 번 보냈다. 이번엔 진짜 마지막이었다.", "I'd let Dad go twice. This time was really the last." },
            { "나는 무릎을 꿇고 도윤이와 엄마를 안았다. 품이 텅 비어 있었다. 내 몸은 이미 절반 이상 빛으로 부서지고 있었다.", "I knelt and hugged Doyun and Mom. My arms held nothing. More than half of me was already breaking into light." },
            { "「울지 마. 나 여기 왔어. 약속 지켰어.」 손이 도윤이의 뺨을, 엄마의 젖은 어깨를 통과했다.", "“Don't cry. I'm here. I kept my promise.” My hands went through Doyun's cheek, through Mom's wet shoulder." },
            { "도윤이 발치에 낡은 라디오가 놓여 있었다. 다이얼 옆에 삐뚤어진 하트.", "An old radio sat at Doyun's feet. A crooked heart beside the dial." },
            { "사라지기 직전, 나는 남은 힘을 다해 라디오 다이얼을 돌렸다. 89.2. 찌르르, 잡음이 일었다.", "Just before I vanished, I turned the radio dial with all I had left. 89.2. A crackle of static." },
            { "도윤이의 눈에서 눈물이 흘러내렸다.", "Tears ran down from Doyun's eyes." },
            { "국화와 우유", "Chrysanthemums and Milk" },
            { "엔딩 A", "Ending A" },
            { "며칠 뒤. 바다가 보이는 언덕에 작은 무덤이 생겼다. 비석에 이름 하나. 고하늘.", "A few days later. A small grave appeared on a hill that looks out on the sea. One name on the stone. Go Haneul." },
            { "도윤이가 무덤 앞에 흰 국화를 내려놓았다. 그 옆에 우유 두 병을 나란히 세웠다.", "Doyun laid white chrysanthemums before the grave. Beside them he set two bottles of milk, side by side." },
            { "도윤이는 한참 비석을 봤다. 바람이 국화를 흔들었다.", "Doyun looked at the stone for a long time. The wind shook the chrysanthemums." },
            { "도윤이는 한참 서 있다가 돌아섰다.", "Doyun stood there a long while, then turned away." },
            { "무덤 앞에 국화와 우유 두 병이 남았다.", "The chrysanthemums and the two bottles of milk stayed in front of the grave." },
            { "그리고……", "And then……" },
            { "미역국", "Seaweed Soup" },
            { "엔딩 B", "Ending B" },
            { "이승을 떠난 영혼의 흔적은 세상에서 지워졌다.", "The traces of a soul that left this world were erased from it." },
            { "마을 사람들은 지난 1년 동안 언덕을 오르내리던 '낯선 여자애'를 모두 잊었다.", "The villagers all forgot the 'strange girl' who'd gone up and down the hill for the past year." },
            { "가게 할머니도, 초소 아저씨도. 「우리 마을에 그런 애가 있었나.」", "Grandma at the store, the man at the guard post. “Was there a girl like that in our village?”" },
            { "엄마만 기억했다. 마루에는 「밥 먹자」라고 쓴 종이가 그대로 있었다.", "Only Mom remembered. On the maru, the paper that said “Let's eat” was still there." },
            { "엄마가 미역국을 끓였다. 빈 마루에 상을 올려놓았다.", "Mom made seaweed soup. She set the table on the empty maru." },
            { "엄마는 마루 끝에 앉아 먼 바다를 봤다. 해가 질 때까지.", "Mom sat at the edge of the maru and looked at the far sea. Until the sun went down." },
            { "등 뒤에서 누가 불렀다. 「엄마.」", "Someone called from behind her. “Mom.”" },
            { "엄마가 천천히 뒤를 돌아봤다. 그리고 환한 얼굴로 손짓했다.", "Mom slowly turned around. Then, her face bright, she waved her in." },
            { "도윤아", "Doyun" },
            { "진엔딩", "True Ending" },
            { "읍내 정류장. 공항 가는 버스가 섰다. 도윤이가 가방을 메고 계단에 발을 올렸다.", "The town bus stop. The bus to the airport pulled in. Doyun, bag on his shoulder, put a foot on the step." },
            { "그 순간, 뒤에서 누가 불렀다. 「도윤아?」", "At that moment, someone called from behind. “Doyun?”" },
            { "도윤이가 돌아봤다. 세상이 하얗게 번졌다. 모든 것이 밝게 빛났다.", "Doyun turned around. The world blurred white. Everything shone bright." },
            { "스튜디오 우히&히시\nYouTube Music · Spotify · iTunes · TIDAL\n「Our frequency」 검색", "Studio Woohee&Heesi\nYouTube Music · Spotify · iTunes · TIDAL\nSearch “Our frequency”" },
            { "Our frequency  —  스튜디오 우히&히시", "Our frequency  —  Studio Woohee&Heesi" },
            { "너와 나의 주파수, 89.2", "Our Frequency, 89.2" },
            { "하나는 오늘, 하나는 내일", "One for today, one for tomorrow" },
            { "노을 전에 닿으면 내가 이기는 놀이", "If I get there before sunset, I win — that game" },
            { "우리의 송전탑", "Our Tower" },
            { "— 회상 · 열한 살 — 처음 가 본 시내 백화점. 유리 안에 파란 보석 머리띠가 있었다. 나는 오래 봤다. 갖고 싶다는 말은 안 했다.", "— Flashback · Age eleven — My first time at a department store in the city. Behind the glass, a blue jeweled headband. I looked a long time. I didn't say I wanted it." },
            { "— 회상 — 그 말이 사치라는 건 열한 살도 알았다. 유리에 손자국만 남기고 돌아섰는데, 아빠가 그 손자국을 보고 있었다.", "— Flashback — Even at eleven I knew saying it was a luxury. I turned away, leaving only a handprint on the glass, and Dad was looking at that handprint." },
            { "— 회상 — 그을린 얼굴, 낡은 점퍼. 아빠가 웃었다. 왼쪽 눈이 접혔다. 「하늘이 생일 선물이 정해졌주.」", "— Flashback — A sunburnt face, a worn jacket. Dad smiled. His left eye creased. “Haneul's birthday present is decided, then.”" },
            { "— 회상 — 아빠는 내 물건마다 빨간 페인트로 하트를 그려 줬다. 가방에도, 신발에도. 삐뚤었다.", "— Flashback — Dad painted a heart in red paint on all my things. On my bag, on my shoes. Crooked." },
            { "— 회상 — 「잃어버리지 말라.」 아빠 주황 우비 소매에도 같은 하트가 있었다.", "— Flashback — “Don't lose 'em, now.” Dad's orange raincoat sleeve had the same heart." },
            { "— 회상 — 해녀 엄마, 배 한 척뿐인 아빠. 머리띠 값은 아빠 한 달 벌이였다.", "— Flashback — A haenyeo mom, a dad with just one boat. The headband cost a month of Dad's earnings." },
            { "— 회상 — 아빠는 이웃에게 돈을 빌려 머리띠를 사 왔고, 빌린 돈을 갚으려면 풍랑주의보가 내린 밤에도 바다에 나가야 했다.", "— Flashback — Dad borrowed money from a neighbor to buy the headband, and to pay it back he had to go to sea even on a night with a storm warning." },
            { "— 회상 — 아빠가 장화를 신었다. 엄마가 아빠 우비를 낚아챘다. 소리는 없었다. 엄마 손이 빠르게 허공을 갈랐다.", "— Flashback — Dad put on his boots. Mom snatched Dad's raincoat. There was no sound. Mom's hands cut fast through the air." },
            { "— 회상 — 가지 마. 엄마 얼굴이 어땠는지는 떠오르지 않는다. 그 손만 떠오른다. 아빠는 그 손을 안 봤다.", "— Flashback — Don't go. I can't bring back what Mom's face looked like. Only those hands. Dad didn't look at those hands." },
            { "— 회상 — 나는 대문턱에서 아빠 소매를 두 손으로 잡았다. 「아빠, 생일 안 해도 돼.」 아빠가 내 머리를 한 번 만졌다.", "— Flashback — At the gate sill I grabbed Dad's sleeve with both hands. “Dad, I don't need a birthday.” Dad touched my head once." },
            { "— 회상 — 「한 마리만 더 잡으민 뒈어, 하늘아.」 하트가 그려진 소매가 손에서 빠져나갔다.", "— Flashback — “Just one more fish and that'll do, Haneul.” The sleeve with the heart slipped out of my hands." },
            { "— 회상 — 젖은 소매의 감촉이 아직도 손에 있다.", "— Flashback — I can still feel the wet sleeve in my hand." },
            { "— 회상 · 다음 날 — 거짓말처럼 맑은 아침이었다. 사람들이 바다로 뛰었다.", "— Flashback · The next day — A morning clear like a lie. People ran to the sea." },
            { "— 회상 — 엄마가 나를 방에 넣고 문을 닫았다. 문틈으로 주황색이 한 번 지나갔다.", "— Flashback — Mom put me in my room and shut the door. Through the gap, a flash of orange went by once." },
            { "— 회상 — 송전탑 아래 바다에 아빠 배가 뒤집혀 있었고, 삐뚤어진 하트가 그려진 부표 하나만 떠 있었다.", "— Flashback — In the sea below the tower, Dad's boat lay upside down, and only one buoy floated, with a crooked heart painted on it." },
            { "— 회상 — 아빠는 돌아오지 않았다. 나는 울지 않았다. 울면 진짜가 될 것 같았다.", "— Flashback — Dad didn't come back. I didn't cry. It felt like crying would make it real." },
            { "— 회상 — 엄마는 그날 노란 통을 열어 보지도 않고 장롱 깊은 데 넣었다. 그날부터 우리 집엔 생일이 없어졌다.", "— Flashback — That day Mom put the yellow case deep in the wardrobe without even opening it. From that day on, our house had no birthdays." },
            { "— 회상 — 아빠가 죽은 뒤, 우리 집은 완전히 소리가 사라졌다. 학교에서는 매일 같은 일이 있었다. 「생선 냄새 나.」", "— Flashback — After Dad died, all sound went out of our house. At school the same thing happened every day. “You smell like fish.”" },
            { "— 회상 — 「벙어리 딸.」 아이들이 도시락을 개수대에 붓고, 가방을 도랑에 던지고, 입만 뻐끔거리며 엄마 흉내를 냈다.", "— Flashback — “The mute's daughter.” Kids dumped my lunch in the sink, threw my bag in the ditch, and mimicked Mom by moving their mouths without sound." },
            { "— 회상 — 나는 매일 못 들은 척했다. 엄마처럼. 집에 와서도 엄마한테 아무 말도 안 했다.", "— Flashback — Every day I pretended not to hear. Like Mom. At home I didn't say anything to Mom either." },
            { "— 회상 — 말해도 못 들으니까. 말할 사람이 없었다. 그게 제일 외로웠다.", "— Flashback — Even if I said it, she couldn't hear. There was no one to talk to. That was the loneliest part." },
            { "— 회상 · 열두 살 봄 — 전학생이 왔다. 서울에서. 몸이 아파서 요양하러 제주에 왔다고 했다.", "— Flashback · Spring, age twelve — A transfer student came. From Seoul. They said he'd come to Jeju to rest because he was sick." },
            { "— 회상 — 흰 셔츠가 눈부셨고, 얼굴은 셔츠만큼 하얬다. 아이들이 그 애를 둘러쌌고 나는 늘 그렇듯 구석에 있었다.", "— Flashback — His white shirt was dazzling, and his face was as white as the shirt. The kids crowded around him, and I stayed in the corner as always." },
            { "— 회상 — 가방이 또 도랑에 던져진 날, 그 애가 도랑에 들어갔다. 흰 셔츠가 진흙투성이가 되도록 가방을 건져 왔다.", "— Flashback — The day my bag got thrown in the ditch again, he climbed into the ditch. He fished the bag out till his white shirt was covered in mud." },
            { "— 회상 — 아이들이 그 애도 밀었다. 그 애는 넘어졌다. 다시 일어나서 내 앞에 섰다. 손이 떨리는 걸 나만 봤다.", "— Flashback — The kids shoved him too. He fell. He got back up and stood in front of me. Only I saw his hands shaking." },
            { "— 회상 — 「싸움도 못하면서 왜 앞을 막아?」 「네가 뒤에 있으니까.」", "— Flashback — “You can't even fight. Why stand in front?” “Because you're behind me.”" },
            { "— 회상 — 그 애는 운동장 구석에 앉아 도시락을 열고 한가운데 선을 그었다. 「반은 네 거.」 계란말이가 따뜻했다.", "— Flashback — He sat in a corner of the schoolyard, opened his lunch box and drew a line down the middle. “Half is yours.” The rolled omelet was warm." },
            { "— 회상 — 나는 그날 처음으로 학교에서 밥을 먹었다. 그 애 이름은 도윤이었다. 도윤이 얼굴은 기억난다. 그 애만은.", "— Flashback — That day I ate at school for the first time. His name was Doyun. I remember Doyun's face. His, at least." },
            { "— 회상 — 그해 봄, 도윤이와 나는 매일 바다에서 놀았다. 도윤이는 서울 애라 수영을 못 했다.", "— Flashback — That spring, Doyun and I played at the sea every day. Doyun was a Seoul kid, so he couldn't swim." },
            { "— 회상 — 나는 얕은 물에서 수영을 가르쳤다. 도윤이는 물을 먹고, 기침을 하고, 다시 들어왔다.", "— Flashback — I taught him to swim in the shallows. Doyun swallowed water, coughed, and went back in." },
            { "— 회상 — 해가 지면 방파제에 나란히 앉아 젖은 옷을 말렸다. 그전까지 나는 웃는 법을 잊고 있었다.", "— Flashback — When the sun went down, we sat side by side on the breakwater and dried our wet clothes. Until then I'd forgotten how to laugh." },
            { "— 회상 — 그 봄에 소리 내서 웃었다. 「너 웃을 줄 아네.」 「시끄러워.」", "— Flashback — That spring I laughed out loud. “So you do know how to laugh.” “Shut up.”" },
            { "— 회상 — 도윤이가 바닷가 바위 틈의 버려진 해녀 불턱을 기지로 꾸몄다.", "— Flashback — Doyun turned an abandoned haenyeo bulteok in the rocks by the shore into a hideout." },
            { "— 회상 — 돌담 안에 담요를 깔고, 고장 난 라디오를 가져다 놓고, 우유를 두 병씩 숨겨 뒀다.", "— Flashback — He spread a blanket inside the stone wall, brought a broken radio, and hid milk there, two bottles at a time." },
            { "— 회상 — 「여긴 우리 기지야.」 라디오를 같이 뜯다가 89.2에서 희미하게 노래가 잡혔다.", "— Flashback — “This is our hideout.” Taking the radio apart together, we caught a faint song at 89.2." },
            { "— 회상 — 도윤이가 다이얼 옆에 하트를 그렸다. 「이 주파수는 우리 거야.」", "— Flashback — Doyun drew a heart beside the dial. “This frequency is ours.”" },
            { "— 회상 — 기지까지는 방파제 길을 보드로 달렸다. 도윤이는 뒤에서 헐떡이며 따라왔다.", "— Flashback — I rode my board down the breakwater road to the hideout. Doyun followed behind, panting." },
            { "— 회상 · 열두 살 생일 — 기지에 들어가니 촛불이 켜져 있었다. 초 열두 개. 도윤이가 케이크 뒤에서 튀어나왔다.", "— Flashback · Twelfth birthday — When I went into the hideout, candles were lit. Twelve of them. Doyun jumped out from behind a cake." },
            { "— 회상 — 「깜짝 선물!」 나는 웃었다. 촛불을 끄고, 케이크를 반씩 먹었다.", "— Flashback — “Surprise!” I laughed. I blew out the candles, and we ate half the cake each." },
            { "— 회상 — 해가 기울자 도윤이가 내 손을 끌었다. 「나머지는 송전탑 가서 먹자. 거기서 노을이 제일 예뻐.」", "— Flashback — As the sun sank, Doyun pulled my hand. “Let's eat the rest at the tower. The sunset's prettiest there.”" },
            { "— 회상 — 손을 뿌리쳤다. 「거기 가자는 말 하지 마.」 「왜? 딱 한 번만.」 「싫다고!」", "— Flashback — I shook off his hand. “Don't ask me to go there.” “Why? Just once.” “I said no!”" },
            { "— 회상 — 케이크 접시가 바위에 떨어졌다. 「모르면서 왜 자꾸 끼어들어!」 도윤이는 한참 나를 봤다.", "— Flashback — The cake plate fell on the rock. “You don't know anything, so why do you keep butting in!” Doyun looked at me a long time." },
            { "— 회상 — 「……미안.」 그리고 갔다. 나는 엎어진 케이크 앞에 혼자 남았다. 촛농이 바위 위에서 식어 갔다.", "— Flashback — “……Sorry.” And he left. I was left alone in front of the overturned cake. Candle wax cooled on the rock." },
            { "— 회상 — 열흘 동안 도윤이는 오지 않았다. 대신 담장 위에 매일 도시락이 놓였다. 첫날은 따뜻했고 열흘째엔 식어 있었다.", "— Flashback — For ten days Doyun didn't come. Instead, a lunch box sat on the wall every day. The first day it was warm; by the tenth it was cold." },
            { "— 회상 — 마지막 도시락 뚜껑 안에 글씨가 있었다. 「친구 아니어도 반은 네 거.」 그날 밤 도윤이 집 앞을 지나갔다.", "— Flashback — Inside the lid of the last lunch box was writing. “Even if we're not friends, half is yours.” That night I walked past Doyun's house." },
            { "— 회상 — 창가에 도윤이가 앉아 송전탑 쪽을 보고 있었다. 오래. 방 벽에 그림이 붙어 있었다.", "— Flashback — Doyun sat at the window, looking toward the tower. For a long time. A drawing was stuck on his wall." },
            { "— 회상 — 송전탑, 노을, 그 아래 케이크를 든 둘. 나는 담 밑에서 그걸 보고 올라가지 못했다.", "— Flashback — The tower, a sunset, and two people under it holding a cake. I saw it from below the wall and couldn't go up." },
            { "— 회상 · 여름 끝 — 그 뒤로 도윤이와 나는 말을 하지 않았다. 학교 복도에서 도윤이가 먼저 다가왔다. 「하늘아, 그날……」", "— Flashback · End of summer — After that, Doyun and I didn't talk. In the school hallway, Doyun came up to me first. “Haneul, that day……”" },
            { "— 회상 — 「됐어. 다시는 말 걸지 마.」 도윤이는 입을 다물었다. 다음 날부터 담장 위에 도시락이 놓이지 않았다.", "— Flashback — “Forget it. Don't ever talk to me again.” Doyun closed his mouth. From the next day, no lunch box sat on the wall." },
            { "— 회상 — 혼자 기지에 가 봤다. 담요는 비에 젖어 있었고, 라디오는 꺼져 있었다. 나는 켜지 않고 돌아왔다.", "— Flashback — I went to the hideout alone. The blanket was soaked with rain, and the radio was off. I came back without turning it on." },
            { "— 회상 · 여름 태풍 — 비가 앞이 안 보이게 쏟아졌다. 양철 지붕이 쉬지 않고 울렸다. 전화가 끊기고 전기도 나갔다.", "— Flashback · Summer typhoon — Rain poured so hard you couldn't see. The tin roof rang without stopping. The phone went dead, and the power went out." },
            { "— 회상 — 촛불을 켰는데 마당에서 소리가 났다. 엄마가 엎어져 있었다. 가슴을 움켜쥐고.", "— Flashback — I lit a candle, and there was a sound in the yard. Mom was lying face down. Clutching her chest." },
            { "— 회상 — 해녀들이 걸리는 심장병이었다. 엄마 얼굴은 이번에도 안 보인다. 젖은 해녀복과 가슴을 쥔 손만 보인다.", "— Flashback — The heart illness haenyeo get. Again I can't see Mom's face. Only the wet diving suit and the hand gripping her chest." },
            { "— 회상 — 우리 집은 언덕 위 외딴집이었다. 제일 가까운 집까지 30분, 병원까지 2킬로. 빗속에 길이 안 보였다.", "— Flashback — Our house was alone on top of the hill. Thirty minutes to the nearest house, 2 km to the hospital. In the rain I couldn't see the road." },
            { "— 회상 — 「엄마! 엄마!」 나는 울부짖었다. 엄마는 못 듣는다. 알면서도 불렀다. 부르는 것밖에 할 게 없었다.", "— Flashback — “Mom! Mom!” I screamed. Mom can't hear. I knew, and I called anyway. Calling was all I could do." },
            { "— 회상 — 마당 끝까지 뛰어가 소리를 질렀다. 「누가 좀 도와주세요!」 빗소리가 내 목소리를 삼켰다. 아무도 없었다.", "— Flashback — I ran to the edge of the yard and shouted. “Somebody help!” The rain swallowed my voice. No one was there." },
            { "— 회상 — 엄마 손이 점점 차가워졌다. 나는 엄마를 안고 울었다. 열두 살이었다. 할 수 있는 게 아무것도 없었다.", "— Flashback — Mom's hand got colder and colder. I held her and cried. I was twelve. There was nothing I could do." },
            { "— 회상 — 빗속에서 손전등 불빛이 올라왔다. 도윤이였다. 우비도 없이 흠뻑 젖어서. 「너 걱정돼서.」", "— Flashback — Through the rain, a flashlight beam came up the hill. It was Doyun. No raincoat, soaked through. “I was worried about you.”" },
            { "— 회상 — 「어떻게 왔어?」 「뛰었어.」 도윤이가 엄마를 보고 얼굴이 굳었다. 그래도 말했다.", "— Flashback — “How did you get here?” “I ran.” Doyun saw Mom and his face went stiff. He said it anyway." },
            { "— 회상 — 「살 수 있어.」 그렇게 말해야 내가 움직이니까. 그 애도 몰랐으면서.", "— Flashback — “She can make it.” He had to say that for me to move. He didn't know either." },
            { "— 회상 — 길가에 낡은 리어카가 있었다. 바퀴가 진흙에 빠져 있었다. 둘이서 끌어냈다. 손톱이 갈라졌다.", "— Flashback — There was an old handcart by the road. Its wheel was stuck in the mud. The two of us dragged it out. My nails split." },
            { "— 회상 — 엄마를 눕히고 도윤이 겉옷을 덮었다. 병원까지 2킬로. 도윤이가 앞에서 끌고 내가 뒤에서 밀었다.", "— Flashback — We laid Mom in it and covered her with Doyun's jacket. 2 km to the hospital. Doyun pulled from the front, I pushed from behind." },
            { "— 회상 — 빗길에 몇 번이나 미끄러졌다. 도윤이 무릎이 꺾였다. 다시 일어났다. 「먼저 가.」", "— Flashback — We slipped again and again on the wet road. Doyun's knees buckled. He got back up. “Go on ahead.”" },
            { "— 회상 — 「싫어. 셋이 같이 가.」 도윤이가 울면서 말했다. 나도 울면서 밀었다. 병원 불빛이 보였다.", "— Flashback — “No. The three of us go together.” Doyun said it crying. I pushed, crying too. The hospital lights came into view." },
            { "— 회상 — 엄마는 살았다. 의사가 그렇게 말했다. 나는 복도 바닥에 주저앉았다.", "— Flashback — Mom lived. The doctor said so. I sank down onto the hallway floor." },
            { "— 회상 — 도윤이가 옆에 앉았다. 「거봐. 살 수 있다고 했잖아.」 그 애 손이 아직 떨리고 있었다.", "— Flashback — Doyun sat next to me. “See? I told you she could make it.” His hands were still shaking." },
            { "— 회상 — 응급실 문이 닫히자 도윤이가 복도에 쓰러졌다. 늘 입술이 파랗게 질려 있던 이유를 나는 그때 처음 알았다.", "— Flashback — When the ER doors closed, Doyun collapsed in the hallway. Only then did I first learn why his lips were always blue." },
            { "— 회상 — 다음 날 도윤이네 집 앞에 검은 차가 서 있었다. 짐이 실리고 있었다.", "— Flashback — The next day a black car stood in front of Doyun's house. Bags were being loaded." },
            { "— 회상 — 「서울 병원으로 가야 한대.」 도윤이 엄마가 울면서 말했다. 「오늘.」", "— Flashback — “He has to go to a hospital in Seoul.” Doyun's mom said it crying. “Today.”" },
            { "— 회상 — 나는 병원에서 엄마 곁에 있다가 그 말을 들었다. 달렸다. 병원에서 도윤이네 집까지 쉬지 않고 달렸다.", "— Flashback — I heard it while I was with Mom at the hospital. I ran. From the hospital to Doyun's house without stopping." },
            { "— 회상 — 숨이 찼다. 그래도 달렸다. 차가 이미 출발하고 있었다. 도윤이가 뒷유리에 붙어서 나를 봤다.", "— Flashback — I was out of breath. I ran anyway. The car was already pulling away. Doyun pressed against the rear window and looked at me." },
            { "— 회상 — 창을 내렸다. 「하늘아! 스무 살 네 생일에 송전탑 아래서 보자! 꼭!」", "— Flashback — He rolled down the window. “Haneul! On your 20th birthday, let's meet under the tower! Promise!”" },
            { "— 회상 — 「우유 두 병 들고 기다릴게! 하나는 오늘, 하나는 내일!」", "— Flashback — “I'll wait with two bottles of milk! One for today, one for tomorrow!”" },
            { "— 회상 — 「알았어! 안 늦을게!」 나는 차를 따라 달리다 넘어졌다. 무릎에서 피가 났다. 안 아팠다.", "— Flashback — “Okay! I won't be late!” I ran after the car and fell. My knee bled. It didn't hurt." },
            { "— 회상 — 그날 밤 달력에 처음으로 글씨를 썼다. 「스무 살 생일, 송전탑 아래, 도윤이.」", "— Flashback — That night I wrote on the calendar for the first time. “20th birthday, under the tower, Doyun.”" },
            { "— 회상 — 연필을 꾹 눌러서 종이가 팼다. 나는 그 약속 하나로 여덟 해를 살았다.", "— Flashback — I pressed the pencil so hard the paper dented. I lived eight years on that one promise." },
            { "지나간다", "Passing by" },
            { "조용해", "Quiet" },
        };
    }
}
